import{_ as a,o as t,c as s,a0 as n}from"./chunks/framework.DQOulFGV.js";const u=JSON.parse('{"title":"Standard Library","description":"","frontmatter":{},"headers":[],"relativePath":"standard-library.md","filePath":"standard-library.md"}'),r={name:"standard-library.md"};function o(i,e,l,p,d,c){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="standard-library" tabindex="-1">Standard Library <a class="header-anchor" href="#standard-library" aria-label="Permalink to &quot;Standard Library&quot;">​</a></h1><p>Mamba comes with a robust standard library exposing system, network, and data parsing utilities natively.</p><h2 id="environment-env" tabindex="-1">Environment (<code>env</code>) <a class="header-anchor" href="#environment-env" aria-label="Permalink to &quot;Environment (`env`)&quot;">​</a></h2><p>Access environment variables provided to the Mamba process.</p><h3 id="env-get" tabindex="-1"><code>env.get()</code> <a class="header-anchor" href="#env-get" aria-label="Permalink to &quot;`env.get()`&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let port = env.get(&quot;PORT&quot;)</span></span></code></pre></div><p><strong>Signature:</strong> <code>env.get(name)</code><strong>Returns:</strong> String representing the environment variable value, or empty if not found.</p><hr><h2 id="json-json" tabindex="-1">JSON (<code>json</code>) <a class="header-anchor" href="#json-json" aria-label="Permalink to &quot;JSON (`json`)&quot;">​</a></h2><p>Native parsing and stringification of JSON data.</p><h3 id="json-stringify" tabindex="-1"><code>json.stringify()</code> <a class="header-anchor" href="#json-stringify" aria-label="Permalink to &quot;`json.stringify()`&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let user = { &quot;name&quot;: &quot;Alex&quot;, &quot;age&quot;: 25 }</span></span>\n<span class="line"><span>let payload = json.stringify(user)</span></span></code></pre></div><p><strong>Signature:</strong> <code>json.stringify(map)</code><strong>Returns:</strong> JSON string representation of the HashMap.</p><h3 id="json-parse" tabindex="-1"><code>json.parse()</code> <a class="header-anchor" href="#json-parse" aria-label="Permalink to &quot;`json.parse()`&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let user_map = json.parse(payload)</span></span></code></pre></div><p><strong>Signature:</strong> <code>json.parse(str)</code><strong>Returns:</strong> HashMap representing the parsed JSON data.</p><hr><h2 id="file-system-file" tabindex="-1">File System (<code>file</code>) <a class="header-anchor" href="#file-system-file" aria-label="Permalink to &quot;File System (`file`)&quot;">​</a></h2><p>Read and write text files synchronously.</p><h3 id="file-read" tabindex="-1"><code>file.read()</code> <a class="header-anchor" href="#file-read" aria-label="Permalink to &quot;`file.read()`&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let content = file.read(&quot;hello.txt&quot;)</span></span></code></pre></div><p><strong>Signature:</strong> <code>file.read(path)</code><strong>Returns:</strong> String content of the file.</p><h3 id="file-write" tabindex="-1"><code>file.write()</code> <a class="header-anchor" href="#file-write" aria-label="Permalink to &quot;`file.write()`&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>file.write(&quot;hello.txt&quot;, &quot;Hello Mamba&quot;)</span></span></code></pre></div><p><strong>Signature:</strong> <code>file.write(path, data)</code><strong>Returns:</strong> Nothing.</p><hr><h2 id="http-client-http" tabindex="-1">HTTP Client (<code>http</code>) <a class="header-anchor" href="#http-client-http" aria-label="Permalink to &quot;HTTP Client (`http`)&quot;">​</a></h2><p>Execute network requests natively.</p><h3 id="http-get" tabindex="-1"><code>http.get()</code> <a class="header-anchor" href="#http-get" aria-label="Permalink to &quot;`http.get()`&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let response = http.get(&quot;https://example.com&quot;)</span></span>\n<span class="line"><span>print(response)</span></span></code></pre></div><p><strong>Signature:</strong> <code>http.get(url)</code><strong>Returns:</strong> String response body.</p><hr><h2 id="string-str" tabindex="-1">String (<code>str</code>) <a class="header-anchor" href="#string-str" aria-label="Permalink to &quot;String (`str`)&quot;">​</a></h2><p>Operations for working with string literals.</p><h3 id="str-upper-str-lower" tabindex="-1"><code>str.upper()</code> &amp; <code>str.lower()</code> <a class="header-anchor" href="#str-upper-str-lower" aria-label="Permalink to &quot;`str.upper()` &amp; `str.lower()`&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let name = &quot;Mamba&quot;</span></span>\n<span class="line"><span>print(str.upper(name))  # &quot;MAMBA&quot;</span></span></code></pre></div><p><strong>Signature:</strong> <code>str.upper(string)</code> / <code>str.lower(string)</code></p><h3 id="str-replace" tabindex="-1"><code>str.replace()</code> <a class="header-anchor" href="#str-replace" aria-label="Permalink to &quot;`str.replace()`&quot;">​</a></h3><div class="language-mamba vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mamba</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let modified = str.replace(&quot;Hello World&quot;, &quot;World&quot;, &quot;Mamba&quot;)</span></span></code></pre></div><p><strong>Signature:</strong> <code>str.replace(string, old, new)</code><strong>Returns:</strong> Modified string.</p>',40)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
